<script setup lang="ts">
import { AlertTriangle, CalendarClock, Check, Send, ShieldCheck, X } from 'lucide-vue-next'
const { api, projectId, apiBase } = useApi()
const { show } = useToast()
const route = useRoute()
const composerOpen = ref(Boolean(route.query.version))
const preparing = ref(false)
const confirming = ref(false)
const plan = ref<any>(null)
const form = reactive({ video_version_id: String(route.query.version || ''), connection_id: 'conn_youtube_demo', platform: 'youtube', title: 'One lesson, three reusable learning assets', caption: 'A practical way to turn one useful lesson into course material, homework and a clear short explanation.', privacy: 'private' })
const { data, refresh } = await useAsyncData('publishing-data', async () => {
  const [videos, connections, publications] = await Promise.all([api<any>(`/v1/projects/${projectId.value}/videos`),api<any>(`/v1/projects/${projectId.value}/connections`),api<any>(`/v1/projects/${projectId.value}/publications`)])
  return { videos: videos.items, connections: connections.items, publications: publications.items }
}, { default: () => ({ videos: [], connections: [], publications: [] }) })
const versions = computed(() => data.value.videos.flatMap((video:any) => (video.versions || []).map((version:any) => ({...version,title:video.title,status:version.status}))))
watchEffect(() => { if (!form.video_version_id && versions.value[0]) form.video_version_id = versions.value[0].id })
const selectedVersion = computed(() => versions.value.find((item:any) => item.id === form.video_version_id))
const selectedConnection = computed(() => data.value.connections.find((item:any) => item.id === form.connection_id))
async function prepare() { preparing.value=true; try { plan.value=await api('/v1/publications',{method:'POST',headers:{'Idempotency-Key':`composer-${Date.now()}`},body:{...form,synthetic_media_disclosure:true,made_for_kids:false}}); show('Publication plan prepared','Review the provider capability warning before commit.','success') } catch(error:any){ show('Could not prepare publication',error.message,'error') } finally{preparing.value=false} }
async function commit(){ confirming.value=true; try{ await api(`/v1/publications/${plan.value.publication_id}/confirm`,{method:'POST',body:{confirmation_token:plan.value.confirmation_token,explicit_consent:plan.value.requires_user_consent}});show('Publication committed','Provider status and metric checkpoints are now tracked.','success');composerOpen.value=false;plan.value=null;await refresh()}catch(error:any){show('Publication failed',error.message,'error')}finally{confirming.value=false}}
</script>
<template><div><UiPageHeader eyebrow="Official adapters" title="Publishing" description="Provider capabilities, consent, status polling and duplicate-safe retries—without browser automation."><button class="button button--primary" @click="composerOpen = true"><Send :size="15" /> Compose publication</button></UiPageHeader><div class="publish-summary"><UiAppCard><span>Ready to publish</span><strong>{{ versions.filter((item:any)=>item.status==='approved').length }}</strong><small>Approved immutable versions</small></UiAppCard><UiAppCard><span>Scheduled</span><strong>{{ data.publications.filter((item:any)=>item.status==='scheduled').length }}</strong><small>Timezone aware</small></UiAppCard><UiAppCard><span>Published</span><strong>{{ data.publications.filter((item:any)=>item.status==='published').length }}</strong><small>Metrics checkpoints created</small></UiAppCard><UiAppCard><span>Needs action</span><strong>{{ data.publications.filter((item:any)=>['awaiting_consent','blocked'].includes(item.status)).length }}</strong><small>Consent or reauthorization</small></UiAppCard></div><UiAppCard class="publishing-table"><div class="section-heading"><div><h2>Publication jobs</h2><p>Queued, uploading, processing and provider terminal states stay distinct.</p></div><ShieldCheck :size="18" /></div><div v-if="data.publications.length" class="table-wrap"><table class="data-table"><thead><tr><th>Title</th><th>Platform</th><th>Status</th><th>Privacy</th><th>Scheduled</th></tr></thead><tbody><tr v-for="item in data.publications" :key="item.id"><td>{{ item.title }}</td><td>{{ item.platform }}</td><td><UiStatusBadge :status="item.status" /></td><td>{{ item.privacy || 'provider choice' }}</td><td>{{ item.scheduled_at || 'Immediate' }}</td></tr></tbody></table></div><div v-else class="empty-state"><div><span class="empty-state__icon"><Send :size="23" /></span><h3>No publication jobs yet</h3><p>Approve a video version, then prepare a two-phase publication plan.</p></div></div></UiAppCard><div v-if="composerOpen" class="modal-backdrop" @click.self="composerOpen=false"><form class="modal publish-modal" @submit.prevent="plan ? commit() : prepare()"><div class="modal__header"><div><h2>Publish composer</h2><p>Fields adapt to actual provider capabilities.</p></div><button type="button" class="icon-button icon-button--plain" @click="composerOpen=false"><X :size="18" /></button></div><div class="modal__body"><div v-if="selectedVersion" class="composer-preview"><video :src="`${apiBase}${selectedVersion.render_url}`" muted playsinline /><div><strong>{{ selectedVersion.title }}</strong><span>{{ selectedVersion.aspect_ratio }} · {{ Math.round(selectedVersion.duration_ms/1000) }} sec</span><UiStatusBadge :status="selectedVersion.status" /></div></div><div class="form-grid"><div class="field field--full"><label>Video version</label><select v-model="form.video_version_id"><option v-for="version in versions" :key="version.id" :value="version.id">{{ version.title }} · {{ version.aspect_ratio }} · {{ version.status }}</option></select></div><div class="field"><label>Platform account</label><select v-model="form.connection_id" @change="form.platform=selectedConnection?.provider || 'youtube'"><option v-for="connection in data.connections" :key="connection.id" :value="connection.id">{{ connection.display_name }} · {{ connection.status }}</option></select></div><div class="field"><label>Privacy</label><select v-model="form.privacy" :disabled="form.platform==='tiktok'"><option value="private">Private</option><option value="unlisted">Unlisted</option><option value="public">Public</option></select></div><div class="field field--full"><label>Title</label><input v-model="form.title" required /></div><div class="field field--full"><label>Caption / description</label><textarea v-model="form.caption" /></div></div><div v-if="form.platform==='tiktok'" class="provider-warning"><AlertTriangle :size="17" /><div><strong>TikTok requires interactive consent</strong><span>Privacy cannot be preselected. Creator info, interaction settings and per-post confirmation are mandatory.</span></div></div><div v-if="plan" class="publication-plan"><Check :size="17" /><div><strong>{{ plan.summary }}</strong><span>{{ plan.requires_user_consent ? 'Explicit consent required' : 'Ready to commit' }}</span><small v-for="warning in plan.warnings" :key="warning">{{ warning }}</small></div></div></div><div class="modal__footer"><button type="button" class="button" @click="composerOpen=false">Cancel</button><button v-if="!plan" class="button button--primary" data-testid="prepare-publication" :disabled="preparing || selectedVersion?.status!=='approved'"><CalendarClock :size="14" /> {{ preparing?'Preparing…':'Prepare plan' }}</button><button v-else class="button button--primary" data-testid="confirm-publication" :disabled="confirming"><Send :size="14" /> {{ confirming?'Publishing…':'Confirm and publish' }}</button></div></form></div></div></template>
<style scoped>.publish-summary{display:grid;grid-template-columns:repeat(4,1fr);gap:12px}.publish-summary .app-card{display:grid;gap:3px;padding:14px 16px}.publish-summary span{color:var(--muted);font-size:8px;text-transform:uppercase}.publish-summary strong{font-family:var(--font-display);font-size:22px}.publish-summary small{color:var(--muted);font-size:8px}.publishing-table{margin-top:15px}.publish-modal{width:min(720px,100%)}.composer-preview{display:flex;align-items:center;gap:12px;margin-bottom:16px;padding:10px;border:1px solid var(--border);border-radius:11px;background:var(--surface-soft)}.composer-preview video{width:70px;height:105px;border-radius:7px;background:#17131f;object-fit:contain}.composer-preview>div{display:grid;gap:4px}.composer-preview strong{font-size:11px}.composer-preview span{color:var(--muted);font-size:8px}.provider-warning,.publication-plan{display:flex;gap:9px;margin-top:14px;padding:10px;border-radius:9px;background:var(--amber-soft);color:#9b6707}.provider-warning>div,.publication-plan>div{display:grid;gap:2px}.provider-warning strong,.publication-plan strong{font-size:9px}.provider-warning span,.publication-plan span,.publication-plan small{font-size:8px;line-height:1.45}.publication-plan{background:var(--green-soft);color:var(--green)}@media(max-width:800px){.publish-summary{grid-template-columns:repeat(2,1fr)}}@media(max-width:500px){.publish-summary{grid-template-columns:1fr}}</style>
